            return 'other', raw
    block('지시문의 단계명 「' + raw + '」이 알려진 품질 단계명(REQ 판정, EC 판정, 명세 판정, 시각 디자인 판정, 최종 판정, 인수 시험, 부적합 기록)으로 시작하지 않습니다.')
try:
    data = json.loads(sys.stdin.buffer.read().decode('utf-8'))
    ti = data.get('tool_input') or {}
    if ti.get('subagent_type') != 'quality':
        sys.exit(0)
    stage, raw = stage_of(ti.get('prompt') or '')
    pm = pm_model(data)
    f = fam(pm)
    if stage == 'final':
        if f in ('fable', 'opus'):
            judge = pm
        elif f == 'sonnet':
            judge = high_id(data)
        else:
            block('PM 모델 ' + pm + '이 알려진 계열(fable, opus, sonnet) 밖이어서 최종 판정의 판정 모델을 정하지 못했습니다.')
    elif stage == 'req':
        if f == 'opus':
            judge = pm
        elif f in ('fable', 'sonnet'):
