        block('품질 서브에이전트 기동을 막았습니다. 단계: ' + raw + ', PM 모델: ' + pm + ', 판정 모델 ID: ' + judge + ', 기동될 모델: ' + launched + ('(호출 인자)' if arg and arg.strip() else '(호출 인자 없음, PM 모델을 이어받음)') + '.')
    sys.exit(0)
except SystemExit:
    raise
except Exception as e:
    say('검사가 오류로 끝나 품질 서브에이전트 기동을 막았습니다: ' + type(e).__name__ + ': ' + str(e) + ACT)
    sys.exit(2)
')" || exit 2
